1	/**
2	 * Credential login, registration and password reset. No third-party provider.
3	 *
4	 * Must call (do not reimplement): hashPassword, verifyPassword, consumeRateLimit, emit
5	 *
6	 * Note: `TaskflowEventMap` has no authentication event and the type is part of
7	 * the frozen contract, so the declared `emit` is not reachable from here.
8	 * Registration still publishes `member.joined` — through
9	 * `OrganizationService.createOrganization`, which owns that membership row.
10	 */
11	import {
12	  hashPassword,
13	  hashToken,
14	  randomToken,
15	  verifyPassword,
16	} from "@/lib/hash";
17	import { consumeRateLimit } from "@/lib/rate-limit";
18	import { slugify } from "@/lib/slug";
19	import * as resetTokenRepo from "@/server/repositories/_password-reset-repository";
20	import * as sessionRepo from "@/server/repositories/session-repository";
21	import * as userRepo from "@/server/repositories/user-repository";
22	import { toIsoTimestamp } from "@/types/common";
23	import { createOrganization } from "./organization-service";
24	import { renderEmail, sendEmail } from "./email-service";
25	import { createSessionToken } from "./session-service";
26	import type {
27	  LoginInput,
28	  PasswordResetConfirmInput,
29	  PasswordResetRequestInput,
30	  RegisterInput,
31	} from "@/schemas/auth";
32	import type { OrgId, SessionId } from "@/types/common";
33	import type { User } from "@/types/member";
34	import type { Organization } from "@/types/organization";
35	
36	/** Buckets guarding the unauthenticated endpoints. */
37	const LOGIN_BUCKET = "auth:login";
38	const RESET_BUCKET = "auth:password-reset";
39	
40	/**
41	 * Rate limiting before a session exists has no tenant to charge against, so
42	 * every unauthenticated attempt is billed to this sentinel bucket.
43	 */
44	const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;
45	
46	/**
47	 * Scopes the login/reset-request buckets to one account, so a burst of
48	 * attempts against one address cannot throttle sign-in or resets for anyone
49	 * else. Addresses are matched case-insensitively, same as `findUserByEmail`.
50	 */
51	export function accountBucket(email: string): OrgId {
52	  return `anon:${email.trim().toLowerCase()}` as OrgId;
53	}
54	
55	/**
56	 * How long a password-reset link stays usable. Links are minted per request
57	 * and opened straight from the inbox, so a short fuse costs nothing and keeps
58	 * a leaked mailbox from being useful later.
59	 */
60	const RESET_TTL_MS = 60 * 60 * 1000;
61	
62	/**
63	 * Registration creates the user and their first workspace in one step — a
64	 * Taskflow account with no organization cannot do anything, so there is no
65	 * intermediate state where one exists without the other.
66	 */
67	export async function register(
68	  input: RegisterInput,
69	): Promise<{ user: User; org: Organization }> {
70	  const existing = await userRepo.findUserByEmail(input.email);
71	  if (existing) {
72	    throw new Error("An account with that email already exists");
73	  }
74	
75	  const user = await userRepo.insertUser({
76	    email: input.email,
77	    name: input.name,
78	    passwordHash: await hashPassword(input.password),
79	  });
80	
81	  const org = await createOrganization(user.id, {
82	    name: `${input.name}'s workspace`,
83	    slug: slugify(input.name) || "workspace",
84	    plan: "free",
85	  });
86	
87	  const welcome = await renderEmail("welcome", {
88	    orgName: org.name,
89	    recipientName: user.name,
90	  });
91	  await sendEmail({ to: user.email, ...welcome });
92	
93	  return { user, org };
94	}
95	
96	/**
97	 * Credential login. The rate limit is charged before the password is checked,
98	 * so a brute-force run is throttled whether or not it guesses correctly, and
99	 * both failure modes return the same message.
100	 */
101	export async function login(
102	  input: LoginInput,
103	): Promise<{ user: User; token: string }> {
104	  const verdict = await consumeRateLimit(
105	    accountBucket(input.email),
106	    LOGIN_BUCKET,
107	  );
108	  if (!verdict.allowed) {
109	    throw new Error("Too many sign-in attempts; try again shortly");
110	  }
111	
112	  const user = await userRepo.findUserByEmail(input.email);
113	  if (!user) throw new Error("Those credentials did not match");
114	
115	  const storedHash = await userRepo.findPasswordHash(user.id);
116	  if (!storedHash || !(await verifyPassword(input.password, storedHash))) {
117	    throw new Error("Those credentials did not match");
118	  }
119	
120	  const { token } = await createSessionToken(user.id, input.rememberMe);
121	
122	  return { user, token };
123	}
124	
125	export async function logout(sessionId: SessionId): Promise<void> {
126	  await sessionRepo.revokeSession(sessionId);
127	}
128	
129	/**
130	 * Always resolves, whether or not the address is known — telling an anonymous
131	 * caller which emails have accounts is an enumeration oracle. Only the token's
132	 * hash is stored; the raw value exists solely inside the email that carries it.
133	 */
134	export async function requestPasswordReset(
135	  input: PasswordResetRequestInput,
136	): Promise<void> {
137	  const verdict = await consumeRateLimit(
138	    accountBucket(input.email),
139	    RESET_BUCKET,
140	  );
141	  if (!verdict.allowed) return;
142	
143	  const user = await userRepo.findUserByEmail(input.email);
144	  if (!user) return;
145	
146	  await resetTokenRepo.invalidateResetTokens(user.id);
147	
148	  const token = randomToken(32);
149	  await resetTokenRepo.issueResetToken(
150	    user.id,
151	    hashToken(token),
152	    toIsoTimestamp(new Date(Date.now() + RESET_TTL_MS)),
153	  );
154	
155	  const message = await renderEmail("password-reset", {
156	    recipientName: user.name,
157	    token,
158	    expiresInMinutes: RESET_TTL_MS / 60_000,
159	  });
160	
161	  await sendEmail({ to: user.email, ...message });
162	}
163	
164	/**
165	 * Consumes a reset token and rewrites the password hash. The token is marked
166	 * used before the new hash is written, so a replay of the same link cannot
167	 * overwrite a password the user has since changed again.
168	 */
169	export async function confirmPasswordReset(
170	  input: PasswordResetConfirmInput,
171	): Promise<User> {
172	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
173	  if (!verdict.allowed) {
174	    throw new Error("Too many reset attempts; try again shortly");
175	  }
176	
177	  const stored = await resetTokenRepo.findLiveResetToken(
178	    hashToken(input.token),
179	  );
180	  if (!stored) throw new Error("That reset link is no longer valid");
181	
182	  await resetTokenRepo.consumeResetToken(stored.id);
183	  await userRepo.updatePasswordHash(
184	    stored.userId,
185	    await hashPassword(input.password),
186	  );
187	  await sessionRepo.revokeAllSessionsForUser(stored.userId);
188	
189	  const user = await userRepo.findUserById(stored.userId);
190	  if (!user) throw new Error("That reset link is no longer valid");
191	
192	  return user;
193	}
